"""Auto-grading library.

Grades three question types via grade(question_spec, student_answer),
returning 1.0 for correct and 0.0 for incorrect. Never raises on
malformed student answers.
"""

import re


def _grade_multiple_choice(spec, answer):
    if not isinstance(answer, str):
        return 0.0
    correct = spec.get("correct")
    if not isinstance(correct, str):
        return 0.0
    return 1.0 if answer.strip().lower() == correct.strip().lower() else 0.0


def _parse_numeric(text):
    """Parse a numeric string; returns float or None if unparseable."""
    if not isinstance(text, str):
        return None
    cleaned = text.strip()
    if not cleaned:
        return None
    # Strip thousands separators: groups of exactly 3 digits after a comma,
    # e.g. '4,500' or '1,234,567'. Leave other commas alone (-> unparseable).
    cleaned = re.sub(r",(?=\d{3}(?:\D|$))", "", cleaned)
    try:
        return float(cleaned)
    except ValueError:
        return None


def _grade_numeric(spec, answer):
    parsed = _parse_numeric(answer) if isinstance(answer, str) else None
    if parsed is None:
        return 0.0

    correct = spec.get("correct")
    try:
        correct = float(correct)
    except (TypeError, ValueError):
        return 0.0

    atol = spec.get("atol", 0)
    rtol = spec.get("rtol", 0)
    try:
        atol = float(atol)
        rtol = float(rtol)
    except (TypeError, ValueError):
        atol, rtol = 0.0, 0.0

    diff = abs(parsed - correct)
    return 1.0 if diff <= atol or diff <= rtol * abs(correct) else 0.0


_PUNCT_TO_STRIP = ".,!?;:'\""


def _normalize_text(text):
    if not isinstance(text, str):
        return ""
    lowered = text.lower()
    stripped = lowered.strip(_PUNCT_TO_STRIP)
    collapsed = " ".join(stripped.split())
    return collapsed


def _grade_short_answer(spec, answer):
    accepted = spec.get("accepted")
    if not isinstance(accepted, (list, tuple)):
        accepted = [accepted]
    normalized = _normalize_text(answer)
    if not normalized:
        return 0.0
    for option in accepted:
        if normalized == _normalize_text(option):
            return 1.0
    return 0.0


_GRADERS = {
    "multiple_choice": _grade_multiple_choice,
    "numeric": _grade_numeric,
    "short_answer": _grade_short_answer,
}


def grade(question_spec, student_answer):
    """Grade a student answer against a question specification.

    Returns 1.0 or 0.0. Unknown question types / malformed specs score 0.0.
    """
    if not isinstance(question_spec, dict):
        return 0.0
    qtype = question_spec.get("type")
    grader = _GRADERS.get(qtype)
    if grader is None:
        return 0.0
    return grader(question_spec, student_answer)

