import pytest

from grader import grade


# ---------------------------------------------------------------------------
# multiple_choice
# ---------------------------------------------------------------------------

class TestMultipleChoice:
    def test_exact_match(self):
        spec = {"type": "multiple_choice", "correct": "B"}
        assert grade(spec, "B") == 1.0

    def test_case_insensitive(self):
        spec = {"type": "multiple_choice", "correct": "B"}
        assert grade(spec, "b") == 1.0
        assert grade(spec, "A") == 1.0 if False else True  # placeholder guard

    def test_case_insensitive_lowercase_spec(self):
        spec = {"type": "multiple_choice", "correct": "c"}
        assert grade(spec, "C") == 1.0

    def test_whitespace_stripped(self):
        spec = {"type": "multiple_choice", "correct": "D"}
        assert grade(spec, "  D ") == 1.0
        assert grade(spec, "\tD\n") == 1.0

    def test_wrong_letter(self):
        spec = {"type": "multiple_choice", "correct": "B"}
        assert grade(spec, "A") == 0.0

    def test_empty_string_answer(self):
        spec = {"type": "multiple_choice", "correct": "B"}
        assert grade(spec, "") == 0.0
        assert grade(spec, "   ") == 0.0

    def test_multi_char_answer_is_wrong(self):
        spec = {"type": "multiple_choice", "correct": "AB"}
        assert grade(spec, "ab") == 1.0
        assert grade(spec, "abc") == 0.0


# ---------------------------------------------------------------------------
# numeric
# ---------------------------------------------------------------------------

class TestNumericParsing:
    def test_plain_integer(self):
        spec = {"type": "numeric", "correct": 42}
        assert grade(spec, "42") == 1.0

    def test_decimal_with_surrounding_whitespace(self):
        spec = {"type": "numeric", "correct": 4.5}
        assert grade(spec, " 4.50 ") == 1.0

    def test_thousands_separators(self):
        spec = {"type": "numeric", "correct": 4500}
        assert grade(spec, "4,500") == 1.0
        assert grade(spec, " 1,234,567 ") == 1.0

    def test_scientific_notation(self):
        spec = {"type": "numeric", "correct": 4500}
        assert grade(spec, "4.5e3") == 1.0
        assert grade(spec, "4.5E3") == 1.0
        assert grade(spec, "-4.5e3") == 1.0

    def test_negative_numbers(self):
        spec = {"type": "numeric", "correct": -3.14}
        assert grade(spec, "-3.14") == 1.0

    def test_non_parseable_scores_zero_without_raising(self):
        spec = {"type": "numeric", "correct": 10}
        assert grade(spec, "hello") == 0.0
        assert grade(spec, "4..5") == 0.0
        assert grade(spec, "--4") == 0.0
        assert grade(spec, "") == 0.0
        assert grade(spec, "   ") == 0.0

    def test_partial_comma_group_not_parsed_as_thousands(self):
        # A comma not followed by exactly 3 digits is invalid input.
        spec = {"type": "numeric", "correct": 45}
        assert grade(spec, "4,50") == 0.0


class TestNumericTolerances:
    def test_missing_tolerances_means_zero(self):
        spec = {"type": "numeric", "correct": 100}
        assert grade(spec, "100") == 1.0
        assert grade(spec, "100.000001") == 0.0

    def test_atol_only(self):
        spec = {"type": "numeric", "correct": 100, "atol": 0.5}
        assert grade(spec, "100.5") == 1.0
        assert grade(spec, "99.5") == 1.0
        assert grade(spec, "100.51") == 0.0

    def test_rtol_only(self):
        spec = {"type": "numeric", "correct": 200, "rtol": 0.01}
        assert grade(spec, "202") == 1.0   # 2 == 0.01 * 200
        assert grade(spec, "198") == 1.0
        assert grade(spec, "202.1") == 0.0

    def test_both_atol_and_rtol_either_passes(self):
        spec = {"type": "numeric", "correct": 1000, "atol": 1, "rtol": 0.05}
        assert grade(spec, "1050") == 1.0  # within rtol
        assert grade(spec, "1001") == 1.0  # within atol only
        assert grade(spec, "1048") == 1.0
        assert grade(spec, "1049.9") == 0.0  # outside both

    def test_exactly_at_atol_boundary_accepted(self):
        spec = {"type": "numeric", "correct": 100, "atol": 2}
        assert grade(spec, "102") == 1.0
        assert grade(spec, "98") == 1.0
        assert grade(spec, "102.0001") == 0.0

    def test_exactly_at_rtol_boundary_accepted(self):
        spec = {"type": "numeric", "correct": 400, "rtol": 0.025}
        assert grade(spec, "410") == 1.0   # 10 == 0.025 * 400
        assert grade(spec, "390") == 1.0
        assert grade(spec, "410.01") == 0.0

    def test_boundary_via_scientific_notation_and_commas(self):
        spec = {"type": "numeric", "correct": 40000, "rtol": 0.01}
        assert grade(spec, "40,400") == 1.0     # boundary
        assert grade(spec, "4.04e4") == 1.0     # boundary
        assert grade(spec, "40,401") == 0.0

    def test_tolerance_around_zero_correct_answer(self):
        # rtol * abs(0) == 0, so only atol can help here.
        spec = {"type": "numeric", "correct": 0, "rtol": 0.5, "atol": 0}
        assert grade(spec, "0") == 1.0
        assert grade(spec, "0.1") == 0.0


# ---------------------------------------------------------------------------
# short_answer
# ---------------------------------------------------------------------------

class TestShortAnswer:
    def test_exact_match(self):
        spec = {"type": "short_answer", "accepted": ["Paris"]}
        assert grade(spec, "Paris") == 1.0

    def test_case_insensitive(self):
        spec = {"type": "short_answer", "accepted": ["Paris"]}
        assert grade(spec, "PARIS") == 1.0
        assert grade(spec, "pArIs") == 1.0

    def test_internal_whitespace_collapsed(self):
        spec = {"type": "short_answer", "accepted": ["New York"]}
        assert grade(spec, "new   york") == 1.0
        assert grade(spec, "  New \t York \n") == 1.0

    def test_punctuation_stripped(self):
        spec = {"type": "short_answer", "accepted": ["Paris"]}
        assert grade(spec, "Paris.") == 1.0
        assert grade(spec, "'Paris!'") == 1.0
        assert grade(spec, '"Paris?"') == 1.0
        assert grade(spec, "Paris;:") == 1.0

    def test_all_punctuation_chars(self):
        spec = {"type": "short_answer", "accepted": ["hello world"]}
        assert grade(spec, "\".,!?;:'hello world'\"!?.,") == 1.0

    def test_multiple_accepted_answers(self):
        spec = {"type": "short_answer", "accepted": ["yes", "yep", "affirmative"]}
        assert grade(spec, "YEP!") == 1.0
        assert grade(spec, "Affirmative.") == 1.0
        assert grade(spec, "nope") == 0.0

    def test_wrong_answer(self):
        spec = {"type": "short_answer", "accepted": ["Paris"]}
        assert grade(spec, "London") == 0.0

    def test_internal_punctuation_preserved(self):
        # Only leading/trailing punctuation is stripped; internal stays.
        spec = {"type": "short_answer", "accepted": ["3.14"]}
        assert grade(spec, "3.14") == 1.0
        assert grade(spec, "314") == 0.0

    def test_empty_string_answer(self):
        spec = {"type": "short_answer", "accepted": ["anything"]}
        assert grade(spec, "") == 0.0
        assert grade(spec, "   ") == 0.0
        assert grade(spec, "...") == 0.0  # punctuation-only strips to empty


# ---------------------------------------------------------------------------
# general / robustness
# ---------------------------------------------------------------------------

class TestGeneral:
    def test_unknown_type_scores_zero(self):
        assert grade({"type": "essay", "correct": "x"}, "x") == 0.0

    def test_malformed_spec_scores_zero(self):
        assert grade(None, "B") == 0.0
        assert grade({"correct": "B"}, "B") == 0.0

